python3 << 'PYEOF'
import json

with open('/tmp/all_data.json') as f:
    raw_data = f.read()

html = r"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Gold Price Dynamics: Trend &amp; Volatility Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js"></script>
<style>
  :root {
    --gold: #C9A94B;
    --gold-light: #E8D5A3;
    --gold-dark: #8B6914;
    --bg: #0D0E12;
    --surface: #13151C;
    --surface2: #1A1D27;
    --surface3: #222536;
    --border: #2A2D3E;
    --text: #E8E9F0;
    --text-muted: #8A8DA0;
    --red: #E05252;
    --green: #4CAF82;
    --blue: #5B8DEF;
    --purple: #9B72CF;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
    --mono: 'Cascadia Code', 'Fira Code', 'Consolas', monospace;
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body { background:var(--bg); color:var(--text); font-family:var(--font); font-size:14px; line-height:1.6; }

  /* Layout */
  .page-header { background:linear-gradient(135deg, #0D0E12 0%, #1A1422 50%, #0D1020 100%); border-bottom:1px solid var(--border); padding:48px 60px 36px; }
  .page-header .label { color:var(--gold); font-size:11px; font-weight:700; letter-spacing:3px; text-transform:uppercase; margin-bottom:12px; }
  .page-header h1 { font-size:32px; font-weight:700; color:#fff; line-height:1.2; margin-bottom:10px; }
  .page-header .subtitle { font-size:15px; color:var(--text-muted); max-width:680px; }
  .page-header .meta { margin-top:20px; display:flex; gap:32px; flex-wrap:wrap; }
  .page-header .meta-item { font-size:12px; color:var(--text-muted); }
  .page-header .meta-item strong { color:var(--gold-light); }

  .container { max-width:1400px; margin:0 auto; padding:0 40px; }

  /* Section */
  .section { padding:48px 60px; border-bottom:1px solid var(--border); }
  .section:last-child { border-bottom:none; }
  .section-header { margin-bottom:32px; }
  .section-number { font-size:11px; color:var(--gold); font-weight:700; letter-spacing:2px; text-transform:uppercase; margin-bottom:6px; }
  .section-title { font-size:22px; font-weight:700; color:#fff; }
  .section-desc { font-size:13px; color:var(--text-muted); margin-top:6px; max-width:800px; }

  /* KPI Cards */
  .kpi-grid { display:grid; grid-template-columns:repeat(5, 1fr); gap:16px; margin-bottom:40px; }
  .kpi-card { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:20px; position:relative; overflow:hidden; }
  .kpi-card::before { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:var(--gold); }
  .kpi-card.negative::before { background:var(--red); }
  .kpi-label { font-size:11px; color:var(--text-muted); font-weight:600; letter-spacing:1px; text-transform:uppercase; margin-bottom:10px; }
  .kpi-value { font-size:28px; font-weight:700; color:var(--gold); font-family:var(--mono); line-height:1; }
  .kpi-card.negative .kpi-value { color:var(--red); }
  .kpi-desc { font-size:11px; color:var(--text-muted); margin-top:8px; line-height:1.4; }

  /* Chart containers */
  .chart-wrap { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:24px; margin-bottom:24px; }
  .chart-title { font-size:14px; font-weight:600; color:var(--text); margin-bottom:4px; }
  .chart-subtitle { font-size:12px; color:var(--text-muted); margin-bottom:20px; }
  .chart-canvas-wrap { position:relative; }

  /* Grid layouts */
  .grid-2 { display:grid; grid-template-columns:1fr 1fr; gap:24px; }
  .grid-3 { display:grid; grid-template-columns:1fr 1fr 1fr; gap:24px; }

  /* Tables */
  .data-table { width:100%; border-collapse:collapse; font-size:13px; }
  .data-table th { color:var(--text-muted); font-weight:600; font-size:11px; letter-spacing:1px; text-transform:uppercase; padding:10px 12px; border-bottom:1px solid var(--border); text-align:left; }
  .data-table td { padding:9px 12px; border-bottom:1px solid rgba(42,45,62,0.5); color:var(--text); }
  .data-table tr:last-child td { border-bottom:none; }
  .data-table tr:hover td { background:rgba(255,255,255,0.02); }
  .data-table .num { font-family:var(--mono); text-align:right; }
  .data-table .pos { color:var(--green); }
  .data-table .neg { color:var(--red); }
  .data-table .sig { color:var(--gold); font-weight:600; }
  .data-table .insig { color:var(--text-muted); }

  /* Regime pills */
  .regime-pill { display:inline-block; padding:2px 8px; border-radius:12px; font-size:11px; font-weight:600; }
  .regime-low { background:rgba(76,175,130,0.15); color:var(--green); border:1px solid rgba(76,175,130,0.3); }
  .regime-mid { background:rgba(201,169,75,0.15); color:var(--gold); border:1px solid rgba(201,169,75,0.3); }
  .regime-high { background:rgba(224,82,82,0.15); color:var(--red); border:1px solid rgba(224,82,82,0.3); }

  /* Insight boxes */
  .insight-box { background:var(--surface2); border-left:3px solid var(--gold); border-radius:0 6px 6px 0; padding:16px 20px; margin-bottom:16px; }
  .insight-box.red { border-left-color:var(--red); }
  .insight-box.blue { border-left-color:var(--blue); }
  .insight-box.green { border-left-color:var(--green); }
  .insight-title { font-size:12px; font-weight:700; color:var(--gold); text-transform:uppercase; letter-spacing:1px; margin-bottom:6px; }
  .insight-box.red .insight-title { color:var(--red); }
  .insight-box.blue .insight-title { color:var(--blue); }
  .insight-box.green .insight-title { color:var(--green); }
  .insight-text { font-size:13px; color:var(--text); line-height:1.6; }

  /* Heatmap */
  .heatmap-wrap { overflow-x:auto; }
  .heatmap-table { border-collapse:collapse; font-size:11px; width:100%; }
  .heatmap-table th { color:var(--text-muted); font-weight:600; padding:4px 6px; text-align:center; font-size:10px; letter-spacing:0.5px; }
  .heatmap-table td { width:48px; height:32px; text-align:center; font-family:var(--mono); font-size:10px; border:1px solid rgba(0,0,0,0.3); cursor:default; transition:opacity .1s; }
  .heatmap-table td:hover { opacity:0.8; outline:1px solid #fff; }
  .heatmap-table .year-label { color:var(--text-muted); font-size:10px; font-weight:600; padding:4px 8px 4px 0; text-align:right; white-space:nowrap; }

  /* Takeaway section */
  .takeaway-grid { display:grid; grid-template-columns:repeat(3, 1fr); gap:20px; margin-bottom:32px; }
  .takeaway-card { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:20px; }
  .takeaway-card .tc-icon { font-size:20px; margin-bottom:12px; }
  .takeaway-card .tc-title { font-size:13px; font-weight:700; color:var(--text); margin-bottom:8px; }
  .takeaway-card .tc-body { font-size:12px; color:var(--text-muted); line-height:1.6; }

  /* Annotation */
