// ---- 7. HEATMAP ----
{
  const years = DATA.heatmap_years;
  const months = DATA.heatmap_months;
  const data = DATA.heatmap_data;

  // Find min/max for color scale
  let allVals = [];
  data.forEach(row => row.forEach(v => { if(v!==null) allVals.push(v); }));
  const minV = Math.min(...allVals);
  const maxV = Math.max(...allVals);

  function volToColor(v) {
    if(v===null) return '#1A1D27';
    // Map to 0-1
    const t = (v - minV) / (maxV - minV);
    // Color: green (low) → gold (mid) → red (high)
    if(t < 0.5) {
      const r = Math.round(76 + (201-76)*t*2);
      const g = Math.round(175 + (169-175)*t*2);
      const b = Math.round(130 + (75-130)*t*2);
      return `rgb(${r},${g},${b})`;
    } else {
      const t2 = (t - 0.5) * 2;
      const r = Math.round(201 + (224-201)*t2);
      const g = Math.round(169 + (82-169)*t2);
      const b = Math.round(75 + (82-75)*t2);
      return `rgb(${r},${g},${b})`;
    }
  }

  function textColor(v) {
    if(v===null) return '#555';
    const t = (v - minV) / (maxV - minV);
    return t > 0.4 ? '#fff' : '#1A1D27';
  }

  let html = '<table class="heatmap-table"><thead><tr><th style="text-align:right;padding-right:8px">Year</th>';
  months.forEach(m => { html += `<th>${m}</th>`; });
  html += '</tr></thead><tbody>';

  years.forEach((y, yi) => {
    html += `<tr><td class="year-label">${y}</td>`;
    data[yi].forEach((v, mi) => {
      const bg = volToColor(v);
      const tc = textColor(v);
      const disp = v !== null ? v.toFixed(0) : '';
      html += `<td style="background:${bg};color:${tc}" title="${months[mi]} ${y}: ${v!==null?v.toFixed(1)+'%':'N/A'}">${disp}</td>`;
    });
    html += '</tr>';
  });
  html += '</tbody></table>';

  // Add color scale legend
  html += `<div style="margin-top:12px;display:flex;align-items:center;gap:12px;font-size:11px;color:#8A8DA0">
    <span>Low vol</span>
    <div style="width:200px;height:8px;border-radius:4px;background:linear-gradient(to right, rgb(76,175,130), rgb(201,169,75), rgb(224,82,82))"></div>
    <span>High vol</span>
    <span style="margin-left:8px;color:#555">(Numbers show annualized % vol)</span>
  </div>`;

  document.getElementById('heatmapContainer').innerHTML = html;
}

