// ---- 10. HISTOGRAM ----
{
  const hist = DATA.hist;
  const xs = hist.map(h => h.x);
  const ns = hist.map(h => h.n);
  const total = ns.reduce((a,b)=>a+b,0);

  // Approximate normal distribution overlay
  const mean = 0.0465;
  const std = 1.1142;
  function normalPdf(x, mu, sigma) {
    return (1/(sigma*Math.sqrt(2*Math.PI))) * Math.exp(-0.5*((x-mu)/sigma)**2) * 0.5 * total;
  }
  const normalOverlay = xs.map(x => normalPdf(x, mean, std));

  const colors = xs.map(x => {
    if(x < -3.1) return 'rgba(155,50,50,0.9)'; // extreme left tail
    if(x < 0) return 'rgba(224,82,82,0.7)';
    if(x > 3.1) return 'rgba(100,155,80,0.9)'; // extreme right tail
    return 'rgba(201,169,75,0.7)';
  });

  const ctx = document.getElementById('histChart').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: xs,
      datasets: [
