          borderWidth:1,
          callbacks: {label: ctx => `${ctx.raw.toFixed(2)}%`}
        }
      },
      scales: {
        x: {ticks:{maxTicksLimit:10, callback:(v,i)=>labels[i]?labels[i].substring(0,7):''}, grid:{color:'rgba(42,45,62,0.4)'}},
        y: {ticks:{callback: v=>v+'%'}, grid:{color:'rgba(42,45,62,0.4)'}}
      }
    }
  });
}

// ---- 4. VOLATILITY CHART ----
{
  const ts = DATA.ts.filter(r => r.v30 !== null);
  const labels = ts.map(r => r.d);
  const v30 = ts.map(r => r.v30);

  const ctx = document.getElementById('volChart').getContext('2d');

  // Color each segment by regime
  const segmentColors = v30.map(v => {
    if (v === null) return 'transparent';
    if (v < 13) return 'rgba(76,175,130,0.8)';
    if (v < 17) return 'rgba(201,169,75,0.8)';
    return 'rgba(224,82,82,0.8)';
  });

  new Chart(ctx, {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: '30d Vol (%)',
          data: v30,
          borderColor: function(ctx) {
            const i = ctx.dataIndex;
            const v = v30[i];
            if (v === null) return 'transparent';
            if (v < 13) return '#4CAF82';
            if (v < 17) return '#C9A94B';
            return '#E05252';
          },
          segment: {
            borderColor: ctx => {
              const v = v30[ctx.p0DataIndex];
              if (v === null) return 'transparent';
              if (v < 13) return '#4CAF82';
              if (v < 17) return '#C9A94B';
              return '#E05252';
            }
          },
          borderWidth: 1.5,
          pointRadius: 0,
          tension: 0.2,
          fill: false
        },
        // Low threshold line
        {label:'Low threshold (13%)', data: labels.map(()=>13), borderColor:'rgba(76,175,130,0.3)', borderWidth:1, borderDash:[4,4], pointRadius:0, fill:false},
        // High threshold line
        {label:'High threshold (17%)', data: labels.map(()=>17), borderColor:'rgba(224,82,82,0.3)', borderWidth:1, borderDash:[4,4], pointRadius:0, fill:false}
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {mode:'index', intersect:false},
      plugins: {
        legend: {display:false},
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {label: ctx => ctx.datasetIndex===0 ? `Vol: ${ctx.raw.toFixed(1)}%` : null}
        }
      },
      scales: {
        x: {ticks:{maxTicksLimit:13, callback:(v,i)=>labels[i]?labels[i].substring(0,7):''}, grid:{color:'rgba(42,45,62,0.4)'}},
        y: {ticks:{callback: v=>v+'%'}, grid:{color:'rgba(42,45,62,0.4)'}, min:0, max:55}
      }
    }
  });
}

// ---- 5. REGIME PIE ----
{
  // Count regime days from vol data
  const volData = DATA.ts.filter(r => r.v30 !== null).map(r => r.v30);
  let low=0, mid=0, high=0;
  volData.forEach(v => { if(v<13) low++; else if(v<17) mid++; else high++; });
  const total = low+mid+high;

  const ctx = document.getElementById('regimePieChart').getContext('2d');
  new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: ['Low Vol (<13%)', 'Mid Vol (13-17%)', 'High Vol (>17%)'],
      datasets: [{
        data: [low, mid, high],
        backgroundColor: ['rgba(76,175,130,0.8)', 'rgba(201,169,75,0.8)', 'rgba(224,82,82,0.8)'],
        borderColor: ['#4CAF82','#C9A94B','#E05252'],
        borderWidth: 2
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {position:'right', labels:{color:'#8A8DA0', font:{size:11}, padding:12}},
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {
            label: ctx => {
              const pct = (ctx.raw/total*100).toFixed(1);
              return ` ${ctx.label}: ${ctx.raw} days (${pct}%)`;
            }
          }
        }
      }
    }
  });
}

// ---- 6. ANNUAL VOL ----
{
  // Compute annual avg vol from ts data
  const annualVol = {};
  DATA.ts.forEach(r => {
    if(r.v30 !== null) {
      const y = r.d.substring(0,4);
      if(!annualVol[y]) annualVol[y] = {sum:0, n:0};
      annualVol[y].sum += r.v30;
      annualVol[y].n++;
    }
  });
  const years = Object.keys(annualVol).sort();
  const avgs = years.map(y => +(annualVol[y].sum/annualVol[y].n).toFixed(1));
  const colors = avgs.map(v => v<13?'rgba(76,175,130,0.8)':v<17?'rgba(201,169,75,0.8)':'rgba(224,82,82,0.8)');

  const ctx = document.getElementById('annualVolChart').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: years,
      datasets: [{
        label: 'Avg Annual Vol (%)',
        data: avgs,
        backgroundColor: colors,
        borderColor: avgs.map(v => v<13?'#4CAF82':v<17?'#C9A94B':'#E05252'),
        borderWidth: 1,
        borderRadius: 2
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {display:false},
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {label: ctx => `${ctx.raw}%`}
        }
      },
      scales: {
        x: {ticks:{font:{size:9}}, grid:{display:false}},
        y: {ticks:{callback: v=>v+'%'}, grid:{color:'rgba(42,45,62,0.4)'}}
      }
    }
  });
}

// ---- 7. HEATMAP ----
{
  const years = DATA.heatmap_years;
  const months = DATA.heatmap_months;
  const data = DATA.heatmap_data;

  // Find min/max for color scale
  let allVals = [];
  data.forEach(row => row.forEach(v => { if(v!==null) allVals.push(v); }));
  const minV = Math.min(...allVals);
  const maxV = Math.max(...allVals);

  function volToColor(v) {
    if(v===null) return '#1A1D27';
    // Map to 0-1
    const t = (v - minV) / (maxV - minV);
    // Color: green (low) → gold (mid) → red (high)
    if(t < 0.5) {
      const r = Math.round(76 + (201-76)*t*2);
      const g = Math.round(175 + (169-175)*t*2);
      const b = Math.round(130 + (75-130)*t*2);
      return `rgb(${r},${g},${b})`;
    } else {
      const t2 = (t - 0.5) * 2;
      const r = Math.round(201 + (224-201)*t2);
      const g = Math.round(169 + (82-169)*t2);
      const b = Math.round(75 + (82-75)*t2);
      return `rgb(${r},${g},${b})`;
    }
  }

  function textColor(v) {
    if(v===null) return '#555';
    const t = (v - minV) / (maxV - minV);
    return t > 0.4 ? '#fff' : '#1A1D27';
  }

  let html = '<table class="heatmap-table"><thead><tr><th style="text-align:right;padding-right:8px">Year</th>';
  months.forEach(m => { html += `<th>${m}</th>`; });
  html += '</tr></thead><tbody>';

  years.forEach((y, yi) => {
    html += `<tr><td class="year-label">${y}</td>`;
    data[yi].forEach((v, mi) => {
      const bg = volToColor(v);
      const tc = textColor(v);
      const disp = v !== null ? v.toFixed(0) : '';
      html += `<td style="background:${bg};color:${tc}" title="${months[mi]} ${y}: ${v!==null?v.toFixed(1)+'%':'N/A'}">${disp}</td>`;
    });
    html += '</tr>';
  });
  html += '</tbody></table>';

  // Add color scale legend
  html += `<div style="margin-top:12px;display:flex;align-items:center;gap:12px;font-size:11px;color:#8A8DA0">
    <span>Low vol</span>
    <div style="width:200px;height:8px;border-radius:4px;background:linear-gradient(to right, rgb(76,175,130), rgb(201,169,75), rgb(224,82,82))"></div>
    <span>High vol</span>
    <span style="margin-left:8px;color:#555">(Numbers show annualized % vol)</span>
  </div>`;

  document.getElementById('heatmapContainer').innerHTML = html;
}

// ---- 8. MONTHLY RETURNS ----
{
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const rets = months.map(m => DATA.monthly[m].mean);
  const tStats = months.map(m => DATA.monthly[m].t);
  const colors = rets.map((v,i) => {
    const sig = Math.abs(tStats[i]) > 2.0;
    if(v >= 0) return sig ? 'rgba(201,169,75,0.9)' : 'rgba(76,175,130,0.5)';
    return sig ? 'rgba(224,82,82,0.9)' : 'rgba(224,82,82,0.45)';
  });

  const ctx = document.getElementById('monthlyRetChart').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: months,
      datasets: [{
        label: 'Avg Daily Return (%)',
        data: rets,
        backgroundColor: colors,
        borderColor: colors.map(c=>c.replace('0.9','1').replace('0.5','0.8').replace('0.45','0.7')),
        borderWidth: 1,
        borderRadius: 3
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {display:false},
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {
            label: (ctx) => {
              const m = months[ctx.dataIndex];
              const t = DATA.monthly[m].t;
              return [`Return: ${ctx.raw.toFixed(4)}%`, `T-stat: ${t.toFixed(3)}`, `Significant: ${Math.abs(t)>2?'YES':'No'}`];
            }
          }
        }
      },
      scales: {
        x: {grid:{display:false}},
        y: {ticks:{callback: v => v.toFixed(3)+'%'}, grid:{color:'rgba(42,45,62,0.5)'}}
      }
    }
  });

  // Populate table
  const tbody = document.getElementById('monthTableBody');
  months.forEach(m => {
    const d = DATA.monthly[m];
    const annualized = (Math.exp(d.mean/100*252)-1)*100;
    const isSig = Math.abs(d.t) >= 2.0;
    const cls = d.mean >= 0 ? 'pos' : 'neg';
    tbody.innerHTML += `<tr>
      <td><strong>${m}</strong></td>
      <td class="num ${cls}">${d.mean.toFixed(4)}%</td>
      <td class="num ${cls}">${annualized.toFixed(1)}%</td>
      <td class="num ${isSig?'sig':'insig'}">${d.t.toFixed(3)}</td>
      <td>${isSig?'<span class="regime-pill regime-high">Significant</span>':'<span style="color:#555;font-size:11px">Not significant</span>'}</td>
      <td style="color:#8A8DA0;font-size:12px">${m==='Jan'?'Strong positive seasonal — rebalancing flows':m==='Aug'?'Significant positive — demand/risk-off':m==='Jun'?'Only negative month — seasonal lull':m==='Oct'?'Near-zero — noise dominant':m==='May'?'Minimal edge — not tradeable':'Positive bias, below significance threshold'}</td>
    </tr>`;
  });
}

// ---- 9. DAY OF WEEK ----
{
  const days = ['Mon','Tue','Wed','Thu','Fri'];
  const vals = days.map(d => DATA.dow[d]);
  const colors = vals.map(v => v >= 0 ? 'rgba(76,175,130,0.7)' : 'rgba(224,82,82,0.7)');

  const ctx = document.getElementById('dowChart').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: days,
      datasets: [{
        label: 'Avg Daily Return (%)',
        data: vals,
        backgroundColor: colors,
        borderRadius: 4,
        borderWidth: 1
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {display:false},
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {label: ctx => `${ctx.raw.toFixed(4)}%`}
        }
      },
      scales: {
        x: {grid:{display:false}},
        y: {ticks:{callback: v=>v.toFixed(3)+'%'}, grid:{color:'rgba(42,45,62,0.4)'}}
      }
    }
  });
}

// ---- 10. HISTOGRAM ----
{
  const hist = DATA.hist;
  const xs = hist.map(h => h.x);
  const ns = hist.map(h => h.n);
  const total = ns.reduce((a,b)=>a+b,0);

  // Approximate normal distribution overlay
  const mean = 0.0465;
  const std = 1.1142;
  function normalPdf(x, mu, sigma) {
    return (1/(sigma*Math.sqrt(2*Math.PI))) * Math.exp(-0.5*((x-mu)/sigma)**2) * 0.5 * total;
  }
  const normalOverlay = xs.map(x => normalPdf(x, mean, std));

  const colors = xs.map(x => {
    if(x < -3.1) return 'rgba(155,50,50,0.9)'; // extreme left tail
    if(x < 0) return 'rgba(224,82,82,0.7)';
    if(x > 3.1) return 'rgba(100,155,80,0.9)'; // extreme right tail
    return 'rgba(201,169,75,0.7)';
  });

  const ctx = document.getElementById('histChart').getContext('2d');
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels: xs,
      datasets: [
        {
          label: 'Actual Count',
          data: ns,
          backgroundColor: colors,
          borderColor: 'transparent',
          borderRadius: 1,
          order: 2
        },
        {
          label: 'Normal Distribution',
          data: normalOverlay,
          type: 'line',
          borderColor: 'rgba(91,141,239,0.8)',
          borderWidth: 2,
          pointRadius: 0,
          tension: 0.4,
          fill: false,
          order: 1
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: {color:'#8A8DA0', font:{size:11}, padding:12}
        },
        tooltip: {
          backgroundColor:'#13151C',
          borderColor:'#2A2D3E',
          borderWidth:1,
          callbacks: {
            title: ctx => `Return: ${ctx[0].label}%`,
            label: ctx => ctx.datasetIndex===0 ? `Count: ${ctx.raw}` : `Normal: ${ctx.raw.toFixed(1)}`
          }
        }
      },
      scales: {
        x: {
          ticks: {callback:(v,i)=>xs[i]%2===0?xs[i]+'%':'', font:{size:9}},
          grid: {display:false}
        },
        y: {ticks:{font:{size:9}}, grid:{color:'rgba(42,45,62,0.4)'}}
      }
    }
  });
}

// ---- 11. MA CROSSOVER CHART (simplified - show price + MAs) ----
{
  const ts = DATA.ts.filter(r => r.m50 !== null && r.m200 !== null);
